async function loadImpactRibbons(){const data=await fetch(new URL('../assets/impact-ribbons.json',import.meta.url)).then(r=>r.json());impactRasters=new Map();for(const [n,frame]of Object.entries(data.frames)){const [x0,y0,x1,y1]=frame.bounds,x=x0-2,y=y0-2,w=x1-x0+4,h=y1-y0+4,canvas=new OffscreenCanvas(w*2,h*2),c=canvas.getContext('2d');c.scale(2,2);c.translate(-x,-y);c.fillStyle='#fff';for(const layer of frame.layers){c.globalAlpha=layer.alpha;c.fill(new Path2D(layer.d),'evenodd');}c.globalAlpha=1;c.globalCompositeOperation='source-in';c.fillStyle=data.color;c.fillRect(x,y,w,h);c.globalCompositeOperation='source-over';impactRasters.set(+n,{canvas,x,y,w,h});}}
function drawImpactRibbons(ctx,f){if(!impactRasters)return;const a=Math.floor(f),t=f-a;ctx.save();for(const[n,weight]of[[a,1-t],[a+1,t]]){const r=impactRasters.get(n);if(r&&weight>0){ctx.globalAlpha=weight;ctx.drawImage(r.canvas,r.x,r.y,r.w,r.h);}}ctx.restore();}
